#!/usr/bin/env python3
"""Drive a program under a pty with fixed size, send keys, capture raw output."""
import os, pty, sys, time, select, fcntl, termios, struct, signal

def main():
    # usage: drive.py <cols> <rows> <outfile> <settle_ms> <script...> -- cmd args...
    # script items: "sleep:ms" or "send:HEX" or "key:NAME"
    cols, rows, outfile = int(sys.argv[1]), int(sys.argv[2]), sys.argv[3]
    settle = int(sys.argv[4])
    script = []
    i = 5
    while sys.argv[i] != '--':
        script.append(sys.argv[i]); i += 1
    cmd = sys.argv[i+1:]

    pid, fd = pty.fork()
    if pid == 0:
        os.execvp(cmd[0], cmd)
        os._exit(127)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))
    out = open(outfile, 'wb')
    def drain(ms):
        end = time.time() + ms/1000.0
        while True:
            r, _, _ = select.select([fd], [], [], max(0, end - time.time()))
            if not r: break
            try:
                data = os.read(fd, 65536)
            except OSError:
                return False
            if not data: return False
            out.write(data); out.flush()
        return True
    drain(settle)
    KEYS = {
        'enter': b'\r', 'tab': b'\t', 'esc': b'\x1b', 'space': b' ',
        'up': b'\x1b[A', 'down': b'\x1b[B', 'right': b'\x1b[C', 'left': b'\x1b[D',
        'backtab': b'\x1b[Z', 'ctrlc': b'\x03', 'ctrld': b'\x04', 'del': b'\x7f',
    }
    for item in script:
        kind, _, val = item.partition(':')
        if kind == 'sleep':
            drain(int(val))
        elif kind == 'send':
            os.write(fd, bytes.fromhex(val)); drain(settle)
        elif kind == 'key':
            os.write(fd, KEYS[val]); drain(settle)
        elif kind == 'char':
            os.write(fd, val.encode()); drain(settle)
    drain(300)
    try:
        os.kill(pid, signal.SIGKILL)
    except ProcessLookupError:
        pass
    _, status = os.waitpid(pid, 0)
    out.close()
    sys.stderr.write(f"exit status: {status}\n")

main()

#!/usr/bin/env python3
"""Minimal terminal emulator: replays a captured byte stream, prints final screen."""
import sys, re

def emulate(data, rows, cols):
    grid = [[' ']*cols for _ in range(rows)]
    r = c = 0
    i = 0
    n = len(data)
    while i < n:
        ch = data[i]
        if ch == 0x1b:
            m = re.match(rb'\x1b\[([0-9;?]*)([a-zA-Z@`~])', data[i:])
            if m:
                params, cmd = m.group(1).decode(), m.group(2).decode()
                i += m.end()
                nums = [int(x) if x else 1 for x in params.lstrip('?').split(';')] if params else [1]
                if cmd == 'A': r = max(0, r - nums[0])
                elif cmd == 'B': r = min(rows-1, r + nums[0])
                elif cmd == 'C': c = min(cols-1, c + nums[0])
                elif cmd == 'D': c = max(0, c - nums[0])
                elif cmd in 'Hf':
                    r = (nums[0]-1) if len(nums)>0 else 0
                    c = (nums[1]-1) if len(nums)>1 else 0
                elif cmd == 'G': c = nums[0]-1
                elif cmd == 'K':
                    if nums[0] in (2,): 
                        grid[r] = [' ']*cols
                    elif nums[0] == 0:
                        for x in range(c, cols): grid[r][x] = ' '
                elif cmd == 'J':
                    if nums[0] == 2:
                        grid = [[' ']*cols for _ in range(rows)]
                continue
            m = re.match(rb'\x1bP[^\x1b]*\x1b\\\\', data[i:])
            if m:
                i += m.end(); continue
            i += 2
            continue
        if ch == 0: i += 1; continue
        if ch == 13: c = 0; i += 1; continue
        if ch == 10: r = min(rows-1, r+1); i += 1; continue
        # decode utf8 char
        m = re.match(rb'[\x00-\x7f]|[\xc0-\xdf][\x80-\xbf]|[\xe0-\xef][\x80-\xbf]{2}|[\xf0-\xf7][\x80-\xbf]{3}', data[i:])
        s = m.group(0).decode('utf8', 'replace')
        i += m.end()
        if c < cols and r < rows:
            grid[r][c] = s
        c += 1
    return [''.join(row) for row in grid]

if __name__ == '__main__':
    data = open(sys.argv[1], 'rb').read()
    rows, cols = int(sys.argv[2]), int(sys.argv[3])
    # optionally: only show state after N frames (count of 'Today is' style redraws)
    for line in emulate(data, rows, cols):
        print(line)

