#!/usr/bin/env python3
"""Extract frames from a pty capture of an FTXUI app.
Usage: frame.py CAPTURE [frame_index]   -- prints that frame raw (default: last)
"""
import sys, re

def frames(data):
    end = data.find(b'\x1b[?1006l')
    if end >= 0:
        data = data[:end]
    start = data.find(b'\x1b[?1006h\x00')
    if start >= 0:
        data = data[start+len(b'\x1b[?1006h\x00'):]
    marker = re.compile(rb'\x1b\[\d+A\x1b\[\d+D\x1b\[\?25[hl](?:\x00)?(?:\x1b\[\d+B\x1b\[\d+C)?')
    out, pos = [], 0
    for m in marker.finditer(data):
        out.append(data[pos:m.end()])
        pos = m.end()
    if pos < len(data):
        out.append(data[pos:])
    return out

if __name__ == '__main__':
    data = open(sys.argv[1], 'rb').read()
    fr = frames(data)
    if len(sys.argv) > 2 and sys.argv[2] == '-n':
        print(len(fr))
    else:
        idx = int(sys.argv[2]) if len(sys.argv) > 2 else -1
        sys.stdout.buffer.write(fr[idx])
        sys.stdout.write('\n')
